-- ========== 0098_weekly_delivery_metrics_v2.sql ==========
-- Weekly delivery metrics v2: adds cost guardrail breach counts.
-- Re-creates the materialized view with two new columns.

BEGIN;

DROP MATERIALIZED VIEW IF EXISTS "public"."weekly_delivery_metrics";

CREATE MATERIALIZED VIEW "public"."weekly_delivery_metrics" AS
WITH project_start AS (
	SELECT
		p."db_id" AS project_db_id,
		p."team_db_id" AS team_db_id,
		coalesce(
			min(pst."created_at") FILTER (WHERE pst."to_status" = 'queued'),
			p."created_at"
		) AS started_at
	FROM "public"."projects" p
	LEFT JOIN "public"."project_status_transitions" pst
		ON pst."project_db_id" = p."db_id"
	GROUP BY p."db_id", p."team_db_id", p."created_at"
),
project_first_done AS (
	SELECT
		pst."project_db_id" AS project_db_id,
		p."team_db_id" AS team_db_id,
		min(pst."created_at") AS done_at
	FROM "public"."project_status_transitions" pst
	INNER JOIN "public"."projects" p
		ON p."db_id" = pst."project_db_id"
	WHERE pst."to_status" = 'done'
	GROUP BY pst."project_db_id", p."team_db_id"
),
cycle_time_weekly AS (
	SELECT
		pfd.team_db_id,
		date_trunc('week', pfd.done_at)::date AS week_start,
		count(*)::int AS completed_projects_count,
		avg(extract(epoch FROM (pfd.done_at - ps.started_at)) / 3600.0)::numeric(12, 2) AS avg_cycle_time_hours
	FROM project_first_done pfd
	INNER JOIN project_start ps
		ON ps.project_db_id = pfd.project_db_id
	WHERE pfd.done_at >= ps.started_at
	GROUP BY pfd.team_db_id, date_trunc('week', pfd.done_at)::date
),
first_client_exit AS (
	SELECT DISTINCT ON (pst."project_db_id")
		pst."project_db_id" AS project_db_id,
		p."team_db_id" AS team_db_id,
		pst."to_status" AS to_status,
		pst."created_at" AS created_at
	FROM "public"."project_status_transitions" pst
	INNER JOIN "public"."projects" p
		ON p."db_id" = pst."project_db_id"
	WHERE pst."from_status" = 'client_review'
	ORDER BY pst."project_db_id", pst."created_at" ASC
),
first_pass_weekly AS (
	SELECT
		fce.team_db_id,
		date_trunc('week', fce.created_at)::date AS week_start,
		count(*) FILTER (WHERE fce.to_status IN ('done', 'in_progress'))::int AS first_pass_total_projects,
		count(*) FILTER (WHERE fce.to_status = 'done')::int AS first_pass_approved_projects
	FROM first_client_exit fce
	GROUP BY fce.team_db_id, date_trunc('week', fce.created_at)::date
),
forced_weekly AS (
	SELECT
		p."team_db_id" AS team_db_id,
		date_trunc('week', pst."created_at")::date AS week_start,
		count(*)::int AS transition_count,
		count(*) FILTER (
			WHERE coalesce((pst."metadata"->>'forced')::boolean, false) = true
		)::int AS forced_transition_count
	FROM "public"."project_status_transitions" pst
	INNER JOIN "public"."projects" p
		ON p."db_id" = pst."project_db_id"
	GROUP BY p."team_db_id", date_trunc('week', pst."created_at")::date
),
cost_guardrail_weekly AS (
	SELECT
		p."team_db_id" AS team_db_id,
		date_trunc('week', pst."created_at")::date AS week_start,
		count(*) FILTER (
			WHERE coalesce((pst."metadata"->'costGuardrail'->>'warningBreached')::boolean, false) = true
		)::int AS cost_warning_breach_count,
		count(*) FILTER (
			WHERE coalesce((pst."metadata"->'costGuardrail'->>'hardStopBreached')::boolean, false) = true
		)::int AS cost_hard_stop_breach_count
	FROM "public"."project_status_transitions" pst
	INNER JOIN "public"."projects" p
		ON p."db_id" = pst."project_db_id"
	WHERE pst."metadata"->'costGuardrail' IS NOT NULL
	GROUP BY p."team_db_id", date_trunc('week', pst."created_at")::date
),
metric_keys AS (
	SELECT team_db_id, week_start FROM cycle_time_weekly
	UNION
	SELECT team_db_id, week_start FROM first_pass_weekly
	UNION
	SELECT team_db_id, week_start FROM forced_weekly
	UNION
	SELECT team_db_id, week_start FROM cost_guardrail_weekly
)
SELECT
	mk.team_db_id,
	mk.week_start,
	coalesce(ct.completed_projects_count, 0) AS completed_projects_count,
	ct.avg_cycle_time_hours,
	coalesce(fp.first_pass_approved_projects, 0) AS first_pass_approved_projects,
	coalesce(fp.first_pass_total_projects, 0) AS first_pass_total_projects,
	CASE
		WHEN coalesce(fp.first_pass_total_projects, 0) > 0
			THEN round((fp.first_pass_approved_projects::numeric / fp.first_pass_total_projects::numeric) * 100.0, 2)
		ELSE NULL
	END AS first_pass_approval_rate,
	coalesce(fw.forced_transition_count, 0) AS forced_transition_count,
	coalesce(fw.transition_count, 0) AS transition_count,
	CASE
		WHEN coalesce(fw.transition_count, 0) > 0
			THEN round((fw.forced_transition_count::numeric / fw.transition_count::numeric) * 100.0, 2)
		ELSE NULL
	END AS forced_transition_rate,
	coalesce(cg.cost_warning_breach_count, 0) AS cost_warning_breach_count,
	coalesce(cg.cost_hard_stop_breach_count, 0) AS cost_hard_stop_breach_count
FROM metric_keys mk
LEFT JOIN cycle_time_weekly ct
	ON ct.team_db_id = mk.team_db_id
	AND ct.week_start = mk.week_start
LEFT JOIN first_pass_weekly fp
	ON fp.team_db_id = mk.team_db_id
	AND fp.week_start = mk.week_start
LEFT JOIN forced_weekly fw
	ON fw.team_db_id = mk.team_db_id
	AND fw.week_start = mk.week_start
LEFT JOIN cost_guardrail_weekly cg
	ON cg.team_db_id = mk.team_db_id
	AND cg.week_start = mk.week_start;

CREATE UNIQUE INDEX IF NOT EXISTS "weekly_delivery_metrics_team_week_uidx"
	ON "public"."weekly_delivery_metrics" ("team_db_id", "week_start");

CREATE INDEX IF NOT EXISTS "weekly_delivery_metrics_week_start_idx"
	ON "public"."weekly_delivery_metrics" ("week_start" DESC);

COMMIT;

-- ========== 0099_delivery_playbooks.sql ==========
-- Delivery Playbooks: reusable project bootstrap templates with phases, SKU, budget, SLA.

BEGIN;

CREATE TABLE IF NOT EXISTS "public"."delivery_playbooks" (
	"db_id"                serial PRIMARY KEY,
	"id"                   text NOT NULL UNIQUE,
	"team_db_id"           integer NOT NULL REFERENCES "public"."teams"("db_id") ON DELETE CASCADE,
	"name"                 text NOT NULL,
	"description"          text,
	"service_sku_db_id"    integer REFERENCES "public"."service_skus"("db_id") ON DELETE SET NULL,
	"default_budget_cents" integer,
	"default_sla_days"     integer NOT NULL DEFAULT 7,
	"name_prefix"          text,
	"phases"               jsonb NOT NULL DEFAULT '[]'::jsonb,
	"checklist"            jsonb NOT NULL DEFAULT '[]'::jsonb,
	"is_active"            boolean NOT NULL DEFAULT true,
	"sort_order"           integer NOT NULL DEFAULT 0,
	"created_at"           timestamp DEFAULT now() NOT NULL,
	"updated_at"           timestamp DEFAULT now() NOT NULL,

	CONSTRAINT "delivery_playbooks_budget_gte_0"
		CHECK ("default_budget_cents" IS NULL OR "default_budget_cents" >= 0),
	CONSTRAINT "delivery_playbooks_sla_gt_0"
		CHECK ("default_sla_days" > 0),
	CONSTRAINT "delivery_playbooks_phases_is_array"
		CHECK (jsonb_typeof("phases") = 'array'),
	CONSTRAINT "delivery_playbooks_checklist_is_array"
		CHECK (jsonb_typeof("checklist") = 'array')
);

CREATE UNIQUE INDEX IF NOT EXISTS "delivery_playbooks_team_name_uidx"
	ON "public"."delivery_playbooks" ("team_db_id", "name");

CREATE INDEX IF NOT EXISTS "delivery_playbooks_team_db_id_idx"
	ON "public"."delivery_playbooks" ("team_db_id");

CREATE INDEX IF NOT EXISTS "delivery_playbooks_is_active_idx"
	ON "public"."delivery_playbooks" ("is_active");

ALTER TABLE "public"."projects"
	ADD COLUMN IF NOT EXISTS "playbook_db_id" integer
		REFERENCES "public"."delivery_playbooks"("db_id") ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS "projects_playbook_db_id_idx"
	ON "public"."projects" ("playbook_db_id");

COMMIT;

-- ========== 0100_better_auth_tables.sql ==========
-- Better Auth migration: add auth tables and email_verified column
-- All existing sessions will be invalidated — users must re-login after deployment.

ALTER TABLE "users" ADD COLUMN "email_verified" boolean NOT NULL DEFAULT false;

CREATE TABLE "auth_sessions" (
  "id" text PRIMARY KEY NOT NULL,
  "user_id" text NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
  "token" text NOT NULL UNIQUE,
  "expires_at" timestamp NOT NULL,
  "ip_address" text,
  "user_agent" text,
  "created_at" timestamp NOT NULL DEFAULT now(),
  "updated_at" timestamp NOT NULL DEFAULT now()
);

CREATE INDEX "auth_sessions_user_id_idx" ON "auth_sessions" ("user_id");
CREATE INDEX "auth_sessions_token_idx" ON "auth_sessions" ("token");

CREATE TABLE "auth_accounts" (
  "id" text PRIMARY KEY NOT NULL,
  "user_id" text NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
  "account_id" text NOT NULL,
  "provider_id" text NOT NULL,
  "access_token" text,
  "refresh_token" text,
  "expires_at" timestamp,
  "scope" text,
  "id_token" text,
  "password" text,
  "created_at" timestamp NOT NULL DEFAULT now(),
  "updated_at" timestamp NOT NULL DEFAULT now(),
  CONSTRAINT "auth_accounts_provider_account_unique" UNIQUE ("provider_id", "account_id")
);

CREATE INDEX "auth_accounts_user_id_idx" ON "auth_accounts" ("user_id");

CREATE TABLE "auth_verifications" (
  "id" text PRIMARY KEY NOT NULL,
  "identifier" text NOT NULL,
  "value" text NOT NULL,
  "expires_at" timestamp NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT now(),
  "updated_at" timestamp NOT NULL DEFAULT now()
);

CREATE INDEX "auth_verifications_identifier_idx" ON "auth_verifications" ("identifier");

-- ========== 0101_migrate_auth_data.sql ==========
-- Data migration: populate Better Auth tables from existing Supabase auth data
-- Run this AFTER deploying the schema migration (0100_better_auth_tables.sql)
-- All existing sessions will be invalidated — users must re-login after deployment.

-- 1. Mark all existing users with supabase mappings as email-verified
UPDATE "users"
SET "email_verified" = true
WHERE "db_id" IN (
  SELECT "user_db_id" FROM "supabase_user_mappings"
);

-- 2. Copy oauth_credentials → auth_accounts
-- Preserving encrypted tokens as-is (same TOKEN_ENCRYPTION_KEY)
INSERT INTO "auth_accounts" ("id", "user_id", "account_id", "provider_id", "access_token", "refresh_token", "expires_at", "scope", "created_at", "updated_at")
SELECT
  'acct_' || gen_random_uuid()::text,
  u."id",                                -- users.id (usr_xxx string)
  oc."provider_account_id",              -- accountId
  oc."provider",                         -- providerId (github/google)
  oc."access_token",                     -- encrypted access token
  oc."refresh_token",                    -- encrypted refresh token
  oc."expires_at",
  oc."scope",
  oc."created_at",
  oc."updated_at"
FROM "oauth_credentials" oc
INNER JOIN "users" u ON u."db_id" = oc."user_id"
ON CONFLICT ("provider_id", "account_id") DO NOTHING;

-- NOTE: No session migration — all users must re-login.
-- The supabase_user_mappings and oauth_credentials tables are kept
-- for rollback safety. Drop them after verifying the migration works
-- (see 0102_cleanup_legacy_auth.sql).

-- ========== 0102_cleanup_legacy_auth.sql ==========
-- Cleanup migration: drop legacy Supabase auth tables
-- ONLY run this after verifying the Better Auth migration is working correctly.
-- This is IRREVERSIBLE — ensure all users can log in via Better Auth first.

-- Drop the legacy bridge table
DROP TABLE IF EXISTS "supabase_user_mappings";

-- Drop the legacy OAuth credentials table (data has been migrated to auth_accounts)
DROP TABLE IF EXISTS "oauth_credentials";

-- Drop the supabaseUserId column from clients (if no longer used)
-- ALTER TABLE "clients" DROP COLUMN IF EXISTS "supabase_user_id";

-- ========== 0103_model_routing_policies.sql ==========
-- Model routing policies + generation cost logs for AI cost tracking.

BEGIN;

CREATE TABLE IF NOT EXISTS "public"."model_routing_policies" (
	"db_id"                            serial PRIMARY KEY,
